    {
      "name": "MvPolynomial.combinatorial_nullstellensatz_exists_eval_nonzero",
      "module_name": "Mathlib.Combinatorics.Nullstellensatz",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {σ : Type u_2} [Finite σ] [IsDomain R] (f : MvPolynomial σ R) (t : σ →₀ ℕ),\n  MvPolynomial.coeff t f ≠ 0 →\n    f.totalDegree = Finsupp.degree t →\n      ∀ (S : σ → Finset R), (∀ (i : σ), t i < (S i).card) → ∃ s, (∀ (i : σ), s i ∈ S i) ∧ (MvPolynomial.eval s) f ≠ 0"
    },
    {
      "name": "MvPolynomial.schwartz_zippel_totalDegree",
      "module_name": "Mathlib.Algebra.MvPolynomial.SchwartzZippel",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] [IsDomain R] [inst_2 : DecidableEq R] {n : ℕ} {p : MvPolynomial (Fin n) R},\n  p ≠ 0 →\n    ∀ (S : Finset R),\n      ↑{f ∈ Fintype.piFinset fun x => S | (MvPolynomial.eval f) p = 0}.card / ↑S.card ^ n ≤ ↑p.totalDegree / ↑S.card"
    },
    {
      "name": "Poly",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "definition",
      "type": "Type u → Type (max 0 u)"
    },
    {
      "name": "MvPolynomial.support_nonempty",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {p : MvPolynomial σ R}, p.support.Nonempty ↔ p ≠ 0"
    },
    {
      "name": "Poly.instInhabited",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "instance",
      "type": "(α : Type u_3) → Inhabited (Poly α)"
    },
    {
      "name": "Polynomial.coeffs_nonempty_iff",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {p : Polynomial R}, p.coeffs.Nonempty ↔ p ≠ 0"
    },
    {
      "name": "MvPolynomial.schwartz_zippel_sup_sum",
      "module_name": "Mathlib.Algebra.MvPolynomial.SchwartzZippel",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] [IsDomain R] [inst_2 : DecidableEq R] {n : ℕ} {p : MvPolynomial (Fin n) R},\n  p ≠ 0 →\n    ∀ (S : Fin n → Finset R),\n      ↑{x ∈ Fintype.piFinset fun i => S i | (MvPolynomial.eval x) p = 0}.card / ∏ i, ↑(S i).card ≤\n        p.support.sup fun s => ∑ i, ↑(s i) / ↑(S i).card"
    },
    {
      "name": "MvPolynomial.support",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → MvPolynomial σ R → Finset (σ →₀ ℕ)"
    }
  ]
}

